// Apply featured flag
export const CARD_SHOWS: CardShow[] = RAW_SHOWS.map(show => ({
  ...show,
  featured: isFeatured(show.name),
}));

// Group shows by state
export function getShowsByState(): StateGroup[] {
  const stateMap = new Map<string, CardShow[]>();
  for (const show of CARD_SHOWS) {
    const existing = stateMap.get(show.state) || [];
    existing.push(show);
    stateMap.set(show.state, existing);
  }
  return Array.from(stateMap.entries())
    .map(([state, shows]) => ({
      state,
      stateName: shows[0].stateName,
      shows: shows.sort((a, b) => a.month - b.month || a.day - b.day),
      featuredCount: shows.filter(s => s.featured).length,
    }))
    .sort((a, b) => a.stateName.localeCompare(b.stateName));
}

// Get total stats
export function getShowStats() {
  const states = new Set(CARD_SHOWS.map(s => s.state));
  return {
    totalShows: CARD_SHOWS.length,
    totalStates: states.size,
    totalFeatured: CARD_SHOWS.filter(s => s.featured).length,
    freeAdmission: CARD_SHOWS.filter(s => s.admission.toLowerCase().includes("free")).length,
  };
}
